### Module 1: Shopping Cart Validation Engine

This component runs validation rules in parallel. It handles asynchronous data lookups to confirm inventory availability, flags pricing discrepancies (detecting outdated cart cache prices), and ensures constraints (e.g., maximum order values) are fully met.

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EnterpriseCheckout.Domain;

namespace EnterpriseCheckout.Validation
{
    public interface ICatalogRepository
    {
        Task<ProductCatalogItem> GetBySkuAsync(string sku, CancellationToken ct = default);
    }

    public interface ICartValidationRule
    {
        Task ValidateAsync(Cart cart, ValidationResultBuilder context, CancellationToken ct = default);
    }

    public class ValidationResultBuilder
    {
        private readonly List<ValidationFailure> _errors = new();
        public bool IsValid => !_errors.Any();
        public IReadOnlyList<ValidationFailure> Errors => _errors;
        public decimal SubTotal { get; set; }
        public decimal Discount { get; set; }
        public decimal Tax { get; set; }
        public decimal TotalPrice => Math.Max(0, SubTotal - Discount + Tax);

        public void AddError(string property, string message)
        {
            _errors.Add(new ValidationFailure(property, message));
        }
    }

    // Rule 1: Checks inventory levels against requested item amounts
    public class StockAvailabilityRule : ICartValidationRule
    {
        private readonly ICatalogRepository _catalogRepository;

        public StockAvailabilityRule(ICatalogRepository catalogRepository)
        {
            _catalogRepository = catalogRepository;
        }

        public async Task ValidateAsync(Cart cart, ValidationResultBuilder context, CancellationToken ct = default)
        {
            foreach (var item in cart.Items)
            {
                var catalogItem = await _catalogRepository.GetBySkuAsync(item.SKU, ct).ConfigureAwait(false);
                if (catalogItem == null)
                {
                    context.AddError(nameof(item.SKU), $"Product SKU '{item.SKU}' was not found in the catalog.");
                    continue;
                }

                if (catalogItem.AvailableStock < item.Quantity)
                {
                    context.AddError(nameof(item.Quantity), 
                        $"Insufficient stock for '{catalogItem.Name}'. Requested: {item.Quantity}, Available: {catalogItem.AvailableStock}.");
                }
            }
        }
    }

    // Rule 2: Validates that submitted prices match the single source of truth database
    public class PriceConsistencyRule : ICartValidationRule
    {
        private readonly ICatalogRepository _catalogRepository;

        public PriceConsistencyRule(ICatalogRepository catalogRepository)
        {
            _catalogRepository = catalogRepository;
        }

        public async Task ValidateAsync(Cart cart, ValidationResultBuilder context, CancellationToken ct = default)
        {
            decimal calculatedSubTotal = 0;

            foreach (var item in cart.Items)
            {
                var catalogItem = await _catalogRepository.GetBySkuAsync(item.SKU, ct).ConfigureAwait(false);
                if (catalogItem == null) continue;

                if (Math.Abs(catalogItem.CurrentPrice - item.UnitPrice) > 0.001m)
                {
                    context.AddError(nameof(item.UnitPrice), 
                        $"Price discrepancy detected for '{catalogItem.Name}'. Catalog: ${catalogItem.CurrentPrice:F2}, Submitted: ${item.UnitPrice:F2}. Please re-add item to your cart.");
                }

                calculatedSubTotal += catalogItem.CurrentPrice * item.Quantity;
            }

            context.SubTotal = calculatedSubTotal;

            // Apply a mock business logic promo rule: "SAVE10" gives 10% off
            if (cart.PromoCode?.Equals("SAVE10", StringComparison.OrdinalIgnoreCase) == true)
            {
                context.Discount = context.SubTotal * 0.10m;
            }

            // Apply standard flat tax: 8.5%
            context.Tax = (context.SubTotal - context.Discount) * 0.085m;
        }
    }

    // Rule 3: Enforces purchase limitations (e.g., maximum transaction ceiling)
    public class PurchaseLimitRule : ICartValidationRule
    {
        private readonly decimal _maxLimit;

        public PurchaseLimitRule(decimal maxLimit = 10000.00m)
        {
            _maxLimit = maxLimit;
        }

        public Task ValidateAsync(Cart cart, ValidationResultBuilder context, CancellationToken ct = default)
        {
            if (cart.Items.Sum(x => x.Quantity) <= 0)
            {
                context.AddError(nameof(cart.Items), "Shopping cart must contain at least one item.");
            }

            if (context.TotalPrice > _maxLimit)
            {
                context.AddError(nameof(context.TotalPrice), $"The absolute maximum transaction size is ${_maxLimit:F2}. Current total: ${context.TotalPrice:F2}.");
            }

            return Task.CompletedTask;
        }
    }

    // Engine Orchestrator executing the individual rules concurrently
    public class CartValidationEngine
    {
        private readonly List<ICartValidationRule> _rules = new();

        public void RegisterRule(ICartValidationRule rule)
        {
            _rules.Add(rule ?? throw new ArgumentNullException(nameof(rule)));
        }

        public async Task<ValidationResult> ValidateCartAsync(Cart cart, CancellationToken ct = default)
        {
            var context = new ValidationResultBuilder();

            // Run structural catalog/pricing rules first to set initial pricing models
            var pricingRules = _rules.Where(r => r is PriceConsistencyRule || r is StockAvailabilityRule);
            var pricingTasks = pricingRules.Select(rule => rule.ValidateAsync(cart, context, ct));
            await Task.WhenAll(pricingTasks).ConfigureAwait(false);

            // Execute final validation rules relying on calculated amounts
            var secondaryRules = _rules.Except(pricingRules);
            foreach (var rule in secondaryRules)
            {
                await rule.ValidateAsync(cart, context, ct).ConfigureAwait(false);
            }

            return new ValidationResult(
                IsSuccess: context.IsValid,
                Errors: context.Errors.ToList(),
                SubTotal: context.SubTotal,
                Discount: context.Discount,
                Tax: context.Tax,
                TotalPrice: context.TotalPrice
            );
        }
    }
}
