### Module 2: Saga Transaction Coordinator

This module handles distributed transaction coordination. If any step fails during checkout (such as card authorization issues or courier booking failures), it automatically initiates structured, reversed compensation operations in exact LIFO (last-in, first-out) order to keep external microservices consistent.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using EnterpriseCheckout.Domain;

namespace EnterpriseCheckout.Saga
{
    #region Service Interfaces

    public interface IInventoryService
    {
        Task<string> ReserveStockAsync(string transactionId, List<CartItem> items, CancellationToken ct = default);
        Task ReleaseStockAsync(string transactionId, string reservationId, CancellationToken ct = default);
    }

    public interface IPaymentService
    {
        Task<string> ProcessPaymentAsync(string transactionId, decimal amount, CancellationToken ct = default);
        Task RefundPaymentAsync(string transactionId, string paymentId, CancellationToken ct = default);
    }

    public interface IShippingService
    {
        Task<(string TrackingId, decimal ShippingCost)> BookCourierAsync(string transactionId, List<CartItem> items, CancellationToken ct = default);
        Task CancelCourierAsync(string transactionId, string trackingId, CancellationToken ct = default);
    }

    #endregion

    #region Mock Microservice Implementations (Thread-Safe)

    public class MockCatalogAndInventoryService : ICatalogRepository, IInventoryService
    {
        private readonly ConcurrentDictionary<string, ProductCatalogItem> _db = new();
        private readonly ConcurrentDictionary<string, List<CartItem>> _reservations = new();

        public MockCatalogAndInventoryService()
        {
            // Seed catalog with dummy stock metrics
            _db.TryAdd("SKU-PRO-01", new ProductCatalogItem("p1", "SKU-PRO-01", "Enterprise Cloud Workstation", 1299.99m, 10));
            _db.TryAdd("SKU-PRO-02", new ProductCatalogItem("p2", "SKU-PRO-02", "UltraWide Developer Monitor", 599.99m, 4));
            _db.TryAdd("SKU-PRO-03", new ProductCatalogItem("p3", "SKU-PRO-03", "Ergonomic Mechanical Keyboard", 149.99m, 50));
        }

        public Task<ProductCatalogItem> GetBySkuAsync(string sku, CancellationToken ct = default)
        {
            _db.TryGetValue(sku, out var item);
            return Task.FromResult(item);
        }

        public async Task<string> ReserveStockAsync(string transactionId, List<CartItem> items, CancellationToken ct = default)
        {
            await Task.Delay(50, ct); // Simulate I/O network lag

            foreach (var item in items)
            {
                if (!_db.TryGetValue(item.SKU, out var dbItem))
                {
                    throw new KeyNotFoundException($"Product '{item.SKU}' no longer present in inventory database.");
                }

                // Atomic transaction safety simulation
                lock (dbItem)
                {
                    if (dbItem.AvailableStock < item.Quantity)
                    {
                        throw new InvalidOperationException($"Out of Stock: Unable to lock down {item.Quantity} units of '{dbItem.Name}'.");
                    }
                    _db[item.SKU] = dbItem with { AvailableStock = dbItem.AvailableStock - item.Quantity };
                }
            }

            var reservationId = $"RES-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";
            _reservations.TryAdd(reservationId, items);
            return reservationId;
        }

        public async Task ReleaseStockAsync(string transactionId, string reservationId, CancellationToken ct = default)
        {
            await Task.Delay(30, ct);
            if (_reservations.TryRemove(reservationId, out var reservedItems))
            {
                foreach (var item in reservedItems)
                {
                    if (_db.TryGetValue(item.SKU, out var dbItem))
                    {
                        lock (dbItem)
                        {
                            _db[item.SKU] = dbItem with { AvailableStock = dbItem.AvailableStock + item.Quantity };
                        }
                    }
                }
            }
        }
    }

    public class MockPaymentService : IPaymentService
    {
        private readonly HashSet<string> _completedCharges = new();
        public bool SimulatePaymentFailure { get; set; } = false;

        public async Task<string> ProcessPaymentAsync(string transactionId, decimal amount, CancellationToken ct = default)
        {
            await Task.Delay(80, ct);

            if (SimulatePaymentFailure)
            {
                throw new TimeoutException("Payment processor Gateway timeout. Authorization failed.");
            }

            var paymentId = $"TXN-{Guid.NewGuid().ToString("N")[..12].ToUpperInvariant()}";
            _completedCharges.Add(paymentId);
            return paymentId;
        }

        public async Task RefundPaymentAsync(string transactionId, string paymentId, CancellationToken ct = default)
        {
            await Task.Delay(40, ct);
            _completedCharges.Remove(paymentId);
        }
    }

    public class MockShippingService : IShippingService
    {
        private readonly HashSet<string> _manifests = new();
        public bool SimulateShippingFailure { get; set; } = false;

        public async Task<(string TrackingId, decimal ShippingCost)> BookCourierAsync(string transactionId, List<CartItem> items, CancellationToken ct = default)
        {
            await Task.Delay(70, ct);

            if (SimulateShippingFailure)
            {
                throw new InvalidOperationException("External shipping partner API returned InternalServerError (500).");
            }

            var trackingId = $"TRK-{Guid.NewGuid().ToString("N")[..10].ToUpperInvariant()}";
            _manifests.Add(trackingId);

            // Flat rate pricing calculation
            decimal shippingCost = 15.00m + (items.Count * 2.50m);
            return (trackingId, shippingCost);
        }

        public async Task CancelCourierAsync(string transactionId, string trackingId, CancellationToken ct = default)
        {
            await Task.Delay(30, ct);
            _manifests.Remove(trackingId);
        }
    }

    #endregion

    #region Saga Coordinator Engine

    public class CheckoutSagaCoordinator
    {
        private readonly IInventoryService _inventoryService;
        private readonly IPaymentService _paymentService;
        private readonly IShippingService _shippingService;
        private readonly Action<string, ConsoleColor> _logger;

        public CheckoutSagaCoordinator(
            IInventoryService inventoryService, 
            IPaymentService paymentService, 
            IShippingService shippingService,
            Action<string, ConsoleColor> logger = null)
        {
            _inventoryService = inventoryService;
            _paymentService = paymentService;
            _shippingService = shippingService;
            _logger = logger ?? ((msg, color) => Console.WriteLine(msg));
        }

        public async Task<OrderDetails> ExecuteAsync(Cart cart, decimal baseAmount, CancellationToken ct = default)
        {
            var state = new SagaState
            {
                CartId = cart.CartId,
                CustomerId = cart.CustomerId,
                Items = cart.Items,
                TotalAmount = baseAmount
            };

            Log($"SAGA [{state.TransactionId}] starting transaction for Customer ID: {state.CustomerId}", ConsoleColor.Cyan);

            try
            {
                // Step 1: Lock down physical warehouse stock
                Log($"SAGA [{state.TransactionId}][STEP 1] Reserving physical inventory items...", ConsoleColor.Yellow);
                state.InventoryReservationId = await _inventoryService.ReserveStockAsync(state.TransactionId, state.Items, ct).ConfigureAwait(false);
                state.IsInventoryReserved = true;
                Log($"SAGA [{state.TransactionId}][STEP 1 SUCCESS] Items reserved. ID: {state.InventoryReservationId}", ConsoleColor.Green);

                // Step 2: Authorize & process financial credit card payment
                Log($"SAGA [{state.TransactionId}][STEP 2] Charging credit card for amount: ${state.TotalAmount:F2}...", ConsoleColor.Yellow);
                state.PaymentTransactionId = await _paymentService.ProcessPaymentAsync(state.TransactionId, state.TotalAmount, ct).ConfigureAwait(false);
                state.IsPaymentCaptured = true;
                Log($"SAGA [{state.TransactionId}][STEP 2 SUCCESS] Payment cleared successfully. Reference: {state.PaymentTransactionId}", ConsoleColor.Green);

                // Step 3: Book shipping manifest
                Log($"SAGA [{state.TransactionId}][STEP 3] Booking courier delivery schedule...", ConsoleColor.Yellow);
                var shippingResult = await _shippingService.BookCourierAsync(state.TransactionId, state.Items, ct).ConfigureAwait(false);
                state.ShippingTrackingId = shippingResult.TrackingId;
                state.ShippingCost = shippingResult.ShippingCost;
                state.IsShippingBooked = true;
                Log($"SAGA [{state.TransactionId}][STEP 3 SUCCESS] Courier dispatched. Tracking: {state.ShippingTrackingId}", ConsoleColor.Green);

                Log($"SAGA [{state.TransactionId}][COMPLETE] Entire distributed workflow committed successfully.", ConsoleColor.Green);

                return new OrderDetails(
                    OrderId: $"ORD-{Guid.NewGuid().ToString("N")[..8].ToUpper()}",
                    CustomerId: state.CustomerId,
                    Items: state.Items,
                    SubTotal: state.TotalAmount,
                    Discount: 0, 
                    Tax: 0,
                    ShippingCost: state.ShippingCost,
                    TotalAmount: state.TotalAmount + state.ShippingCost,
                    TransactionId: state.PaymentTransactionId,
                    TrackingId: state.ShippingTrackingId,
                    OrderDate: DateTime.UtcNow
                );
            }
            catch (Exception ex)
            {
                Log($"SAGA [{state.TransactionId}][FAILURE DETECTED] Error: '{ex.Message}'. Commencing dynamic fallback rollback...", ConsoleColor.Red);
                await RollbackAsync(state, CancellationToken.None).ConfigureAwait(false);
                throw;
            }
        }

        private async Task RollbackAsync(SagaState state, CancellationToken ct)
        {
            // Execute rollback in reverse order (LIFO)

            // Rollback Shipping manifest first
            if (state.IsShippingBooked)
            {
                Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 3] Voiding courier booking: {state.ShippingTrackingId}...", ConsoleColor.DarkYellow);
                try
                {
                    await _shippingService.CancelCourierAsync(state.TransactionId, state.ShippingTrackingId, ct).ConfigureAwait(false);
                    Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 3] Courier booking cancelled successfully.", ConsoleColor.Gray);
                }
                catch (Exception ex)
                {
                    Log($"CRITICAL: Compensation step failed while cancelling shipment: {ex.Message}", ConsoleColor.Magenta);
                }
            }

            // Rollback Payment next (Refund)
            if (state.IsPaymentCaptured)
            {
                Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 2] Issuing full credit card refund for reference: {state.PaymentTransactionId}...", ConsoleColor.DarkYellow);
                try
                {
                    await _paymentService.RefundPaymentAsync(state.TransactionId, state.PaymentTransactionId, ct).ConfigureAwait(false);
                    Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 2] Refund processed successfully.", ConsoleColor.Gray);
                }
                catch (Exception ex)
                {
                    Log($"CRITICAL: Compensation step failed while refunding payment: {ex.Message}", ConsoleColor.Magenta);
                }
            }

            // Rollback Inventory Reservation last (Release stock lock)
            if (state.IsInventoryReserved)
            {
                Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 1] Releasing physical warehouse inventory locks: {state.InventoryReservationId}...", ConsoleColor.DarkYellow);
                try
                {
                    await _inventoryService.ReleaseStockAsync(state.TransactionId, state.InventoryReservationId, ct).ConfigureAwait(false);
                    Log($"SAGA [{state.TransactionId}][ROLLBACK - STEP 1] Warehouse inventory stock unlocked.", ConsoleColor.Gray);
                }
                catch (Exception ex)
                {
                    Log($"CRITICAL: Compensation step failed while releasing inventory: {ex.Message}", ConsoleColor.Magenta);
                }
            }

            Log($"SAGA [{state.TransactionId}][ROLLBACK COMPLETE] Local system state reverted to consistent state.", ConsoleColor.Cyan);
        }

        private void Log(string message, ConsoleColor color) => _logger(message, color);
    }

    #endregion
}
```

