### Module 3: Invoice Generator (Pure PDF Stream Writer)

This high-performance engine constructs clean, specification-compliant **PDF documents** writing binary strings directly to a Stream. It calculates structural stream lengths and offsets, rendering tables, horizontal lines, header graphics, meta boxes, and calculated transaction totals with zero dependencies.

```csharp
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using EnterpriseCheckout.Domain;

namespace EnterpriseCheckout.Invoicing
{
    public interface IInvoiceGenerator
    {
        byte[] GenerateInvoicePdf(OrderDetails order);
    }

    public class PdfInvoiceGenerator : IInvoiceGenerator
    {
        public byte[] GenerateInvoicePdf(OrderDetails order)
        {
            using var ms = new MemoryStream();
            using var writer = new StreamWriter(ms, Encoding.ASCII);

            var pdfObjects = new List<string>();
            var byteOffsets = new List<long>();

            // Header Elements (Catalog and Resource dictionaries)
            pdfObjects.Add("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj");
            pdfObjects.Add("2 0 obj\n<< /Type /Pages /Kids [ 3 0 R ] /Count 1 >>\nendobj");
            pdfObjects.Add("3 0 obj\n<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /MediaBox [ 0 0 595 842 ] /Contents 6 0 R >>\nendobj");
            pdfObjects.Add("4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\nendobj");
            pdfObjects.Add("5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj");

            // Build dynamic text & line paths inside Document stream
            var contentStream = BuildInvoiceLayoutText(order);
            pdfObjects.Add($"6 0 obj\n<< /Length {contentStream.Length} >>\nstream\n{contentStream}\nendstream\nendobj");

            // Write PDF Header
            writer.Write("%PDF-1.4\n");
            writer.Flush();
            long currentOffset = 9; // Size of "%PDF-1.4\n" in bytes

            // Write Objects dynamically recording cross-references
            for (int i = 0; i < pdfObjects.Count; i++)
            {
                byteOffsets.Add(currentOffset);
                var objBytes = Encoding.ASCII.GetBytes(pdfObjects[i] + "\n");
                ms.Write(objBytes, 0, objBytes.Length);
                currentOffset += objBytes.Length;
            }

            // Cross-Reference Table (XREF) Offset
            long xrefOffset = currentOffset;
            writer.Flush();

            // Write XREF Structure
            var xrefStringBuilder = new StringBuilder();
            xrefStringBuilder.Append("xref\n");
            xrefStringBuilder.Append($"0 {pdfObjects.Count + 1}\n");
            xrefStringBuilder.Append("0000000000 65535 f \n");

            for (int i = 0; i < pdfObjects.Count; i++)
            {
                xrefStringBuilder.Append($"{byteOffsets[i]:D10} 00000 n \n");
            }

            xrefStringBuilder.Append("trailer\n");
            xrefStringBuilder.Append($"<< /Size {pdfObjects.Count + 1} /Root 1 0 R >>\n");
            xrefStringBuilder.Append("startxref\n");
            xrefStringBuilder.Append($"{xrefOffset}\n");
            xrefStringBuilder.Append("%%EOF");

            var trailerBytes = Encoding.ASCII.GetBytes(xrefStringBuilder.ToString());
            ms.Write(trailerBytes, 0, trailerBytes.Length);
            ms.Flush();

            return ms.ToArray();
        }

        private string BuildInvoiceLayoutText(OrderDetails order)
        {
            var sb = new StringBuilder();

            // Vector Graphics Drawing: Colored header block
            sb.Append("0.082 0.396 0.753 rg\n"); // Enterprise Indigo
            sb.Append("30 750 535 55 re\n");    // Background header bar rectangle
            sb.Append("f\n");

            // White text inside Title block
            sb.Append("BT\n");
            sb.Append("/F1 20 Tf\n");
            sb.Append("1 g\n"); // White text color
            sb.Append("50 772 Td\n");
            sb.Append("(ENTERPRISE BILLING INVOICE) Tj\n");
            sb.Append("ET\n");

            // Gray Horizontal Line Dividers
            sb.Append("0.75 w\n");
            sb.Append("0.5 G\n"); // Dark grey stroke
            sb.Append("30 630 m 565 630 l S\n"); // Horizontal separator line below header
            sb.Append("30 430 m 565 430 l S\n"); // Line separating products and totals

            // Left side Company meta metadata text block
            sb.Append("BT\n");
            sb.Append("/F2 10 Tf\n");
            sb.Append("0 g\n"); // Black text color
            sb.Append("30 710 Td\n");
            sb.Append($"(Order Identification: {order.OrderId}) Tj\n");
            sb.Append("T*\n");
            sb.Append($"(Payment Reference: {order.TransactionId}) Tj\n");
            sb.Append("T*\n");
            sb.Append($"(Logistics Tracker: {order.TrackingId}) Tj\n");
            sb.Append("T*\n");
            sb.Append($"(Invoice Timestamp: {order.OrderDate.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture)} UTC) Tj\n");
            sb.Append("ET\n");

            // Right side Corporate Brand metadata text block
            sb.Append("BT\n");
            sb.Append("/F1 11 Tf\n");
            sb.Append("400 710 Td\n");
            sb.Append("(E-Commerce Platform Inc.) Tj\n");
            sb.Append("/F2 10 Tf\n");
            sb.Append("T*\n");
            sb.Append("(100 Tech Corporate Blvd) Tj\n");
            sb.Append("T*\n");
            sb.Append("(Suite 500, Silicon Valley) Tj\n");
            sb.Append("ET\n");

            // Render Table Header Line
            sb.Append("BT\n");
            sb.Append("/F1 10 Tf\n");
            sb.Append("30 610 Td\n");
            sb.Append("(Item SKU) Tj\n");
            sb.Append("120 0 Td\n");
            sb.Append("(Product Description) Tj\n");
            sb.Append("240 0 Td\n");
            sb.Append("(Quantity) Tj\n");
            sb.Append("80 0 Td\n");
            sb.Append("(Unit Price) Tj\n");
            sb.Append("80 0 Td\n");
            sb.Append("(Extended Total) Tj\n");
            sb.Append("ET\n");

            // Render Shopping Cart Items Inside Dynamic PDF Lines
            int yPos = 580;
            foreach (var item in order.Items)
            {
                var escapedSku = CleanForPdf(item.SKU);
                var escapedName = CleanForPdf(item.Name);
                var qtyStr = item.Quantity.ToString(CultureInfo.InvariantCulture);
                var priceStr = $"${item.UnitPrice.ToString("F2", CultureInfo.InvariantCulture)}";
                var totalStr = $"${(item.Quantity * item.UnitPrice).ToString("F2", CultureInfo.InvariantCulture)}";

                sb.Append("BT\n");
                sb.Append("/F2 9 Tf\n");
                sb.Append($"30 {yPos} Td\n");
                sb.Append($"({escapedSku}) Tj\n");
                sb.Append($"120 0 Td\n");
                sb.Append($"({escapedName}) Tj\n");
                sb.Append($"240 0 Td\n");
                sb.Append($"({qtyStr}) Tj\n");
                sb.Append($"80 0 Td\n");
                sb.Append($"({priceStr}) Tj\n");
                sb.Append($"80 0 Td\n");
                sb.Append($"({totalStr}) Tj\n");
                sb.Append("ET\n");

                yPos -= 25;
            }

            // SubTotal Box / Tax / Total Pricing Block
            int subtotalBoxY = 400;
            sb.Append("BT\n");
            sb.Append("/F2 10 Tf\n");
            sb.Append($"360 {subtotalBoxY} Td\n");
            sb.Append($"(Subtotal Amount:) Tj\n");
            sb.Append($"130 0 Td\n");
            sb.Append($"(${order.SubTotal.ToString("F2", CultureInfo.InvariantCulture)}) Tj\n");
            sb.Append("ET\n");

            sb.Append("BT\n");
            sb.Append("/F2 10 Tf\n");
            sb.Append($"360 {subtotalBoxY - 20} Td\n");
            sb.Append($"(Logistics Fees:) Tj\n");
            sb.Append($"130 0 Td\n");
            sb.Append($"(${order.ShippingCost.ToString("F2", CultureInfo.InvariantCulture)}) Tj\n");
            sb.Append("ET\n");

            sb.Append("BT\n");
            sb.Append("/F1 11 Tf\n");
            sb.Append($"360 {subtotalBoxY - 45} Td\n");
            sb.Append($"(Total Settled Invoice Balance:) Tj\n");
            sb.Append($"130 0 Td\n");
            sb.Append($"(${order.TotalAmount.ToString("F2", CultureInfo.InvariantCulture)}) Tj\n");
            sb.Append("ET\n");

            // Final PDF bottom signature footer text
            sb.Append("BT\n");
            sb.Append("/F2 9 Tf\n");
            sb.Append("0.4 g\n"); // Grey text
            sb.Append("120 80 Td\n");
            sb.Append("(This statement was generated electronically. Thank you for your business!) Tj\n");
            sb.Append("ET\n");

            return sb.ToString();
        }

        private static string CleanForPdf(string text)
        {
            // Escape parenthesis to prevent layout corruption
            return text.Replace("(", "\\(").Replace(")", "\\)");
        }
    }
}
