### Executable Sandbox Demo

Compile this orchestration harness to run three simulated checkouts: a **successful checkout**, an **inventory overflow rejection**, and a **fully executed payment rollback**.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using EnterpriseCheckout.Domain;
using EnterpriseCheckout.Invoicing;
using EnterpriseCheckout.Saga;
using EnterpriseCheckout.Validation;

namespace EnterpriseCheckout
{
    public class Program
    {
        public static async Task Main(string[] args)
        {
            Console.OutputEncoding = System.Text.Encoding.UTF8;
            Console.Clear();
            Console.WriteLine("=========================================================================");
            Console.WriteLine("        ENTERPRISE CHECKOUT ORCHESTRATOR DEMO RUNTIME BOARD");
            Console.WriteLine("=========================================================================\n");

            // Initializing Shared Infrastructures & Services
            var catalogAndInventory = new MockCatalogAndInventoryService();
            var paymentService = new MockPaymentService();
            var shippingService = new MockShippingService();
            var invoiceGenerator = new PdfInvoiceGenerator();

            // Register global logging callback helper
            Action<string, ConsoleColor> consoleLogger = (text, color) =>
            {
                var oldColor = Console.ForegroundColor;
                Console.ForegroundColor = color;
                Console.WriteLine(text);
                Console.ForegroundColor = oldColor;
            };

            var sagaCoordinator = new CheckoutSagaCoordinator(
                catalogAndInventory, 
                paymentService, 
                shippingService, 
                consoleLogger
            );

            // Construct Cart validation Engine Rules Pipeline
            var validationEngine = new CartValidationEngine();
            validationEngine.RegisterRule(new StockAvailabilityRule(catalogAndInventory));
            validationEngine.RegisterRule(new PriceConsistencyRule(catalogAndInventory));
            validationEngine.RegisterRule(new PurchaseLimitRule(12000.00m)); // Hard limits

            // ------------------------------------------------------------------------
            // SCENARIO 1: SUCCESSFUL CHECKOUT FLOW -> GENERATE PDF INVOICE
            // ------------------------------------------------------------------------
            Console.WriteLine("\n[SCENARIO 1] Executing highly valid shopping cart transaction pipeline...");

            var validCart = new Cart(
                CartId: "CART-8899",
                CustomerId: "CUST-992",
                Items: new List<CartItem>
                {
                    new("p1", "SKU-PRO-01", "Enterprise Cloud Workstation", 1299.99m, 2),
                    new("p2", "SKU-PRO-02", "UltraWide Developer Monitor", 599.99m, 1)
                },
                PromoCode: "SAVE10" // Apply 10% Discount Rule
            );

            // Trigger Step 1: Validation Engine Pipeline
            var validationReport = await validationEngine.ValidateCartAsync(validCart);
            RenderValidationOutput(validationReport);

            if (validationReport.IsSuccess)
            {
                try
                {
                    // Trigger Step 2: Distributed Saga Coordination
                    var order = await sagaCoordinator.ExecuteAsync(validCart, validationReport.TotalPrice);

                    // Trigger Step 3: Raw PDF Generator
                    var pdfBytes = invoiceGenerator.GenerateInvoicePdf(order);
                    var filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, $"Invoice_{order.OrderId}.pdf");
                    await File.WriteAllBytesAsync(filePath, pdfBytes);

                    Console.ForegroundColor = ConsoleColor.Green;
                    Console.WriteLine($"\n✔ SUCCESS: PDF Invoice printed on physical disk footprint location:\n  --> {filePath}");
                    Console.ResetColor();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"✘ Unexpected Runtime System crash: {ex.Message}");
                }
            }

            // ------------------------------------------------------------------------
            // SCENARIO 2: PRE-VALIDATION ENGINE REJECTION (Pricing Error & Out of Stock)
            // ------------------------------------------------------------------------
            Console.WriteLine("\n\n=========================================================================");
            Console.WriteLine("[SCENARIO 2] Executing invalid shopping cart to trigger Pre-Saga Validation rejection...");

            var invalidCart = new Cart(
                CartId: "CART-9900",
                CustomerId: "CUST-112",
                Items: new List<CartItem>
                {
                    new("p1", "SKU-PRO-01", "Enterprise Cloud Workstation", 99.00m, 1),   // Stale hack price
                    new("p2", "SKU-PRO-02", "UltraWide Developer Monitor", 599.99m, 20) // Way above current stock limit
                }
            );

            var validationReportFailed = await validationEngine.ValidateCartAsync(invalidCart);
            RenderValidationOutput(validationReportFailed);

            if (!validationReportFailed.IsSuccess)
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine("✔ Engine successfully intercepted anomalous cart data before passing to payment gateways!");
                Console.ResetColor();
            }

            // ------------------------------------------------------------------------
            // SCENARIO 3: SAGA COORDINATOR COMPENSATION ROLLBACK (Failed Shipping Step)
            // ------------------------------------------------------------------------
            Console.WriteLine("\n\n=========================================================================");
            Console.WriteLine("[SCENARIO 3] Executing high-value checkout where Payment fails -> Trigger automated Saga compensating rollbacks...");

            // Trigger payment failures intentionally in third party mock API
            paymentService.SimulatePaymentFailure = true;

            var validCartFailedWorkflow = new Cart(
                CartId: "CART-7711",
                CustomerId: "CUST-331",
                Items: new List<CartItem>
                {
                    new("p3", "SKU-PRO-03", "Ergonomic Mechanical Keyboard", 149.99m, 2)
                }
            );

            var validationResultStep3 = await validationEngine.ValidateCartAsync(validCartFailedWorkflow);
            RenderValidationOutput(validationResultStep3);

            if (validationResultStep3.IsSuccess)
            {
                try
                {
                    await sagaCoordinator.ExecuteAsync(validCartFailedWorkflow, validationResultStep3.TotalPrice);
                }
                catch (Exception ex)
                {
                    Console.ForegroundColor = ConsoleColor.Red;
                    Console.WriteLine($"\n✔ Transaction rejected cleanly! Reason: '{ex.Message}'");
                    Console.ForegroundColor = ConsoleColor.Green;
                    Console.WriteLine("✔ Check logs above: Distributed transactions were cleanly rolled back via compensating events!");
                    Console.ResetColor();
                }
            }

            Console.WriteLine("\n=========================================================================");
            Console.WriteLine("DEMO WORKFLOW RUN COMPLETED.");
            Console.WriteLine("=========================================================================");
        }

        private static void RenderValidationOutput(ValidationResult result)
        {
            Console.WriteLine("\n--- Shopping Cart Validation Report ---");
            if (result.IsSuccess)
            {
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine("  STATUS: Cart Approved (PASS)");
                Console.ForegroundColor = ConsoleColor.Gray;
                Console.WriteLine($"  Calculated Subtotal: ${result.SubTotal:F2}");
                Console.WriteLine($"  Promo Code Discount: -${result.Discount:F2}");
                Console.WriteLine($"  Applied Sales Taxes: ${result.Tax:F2}");
                Console.WriteLine($"  Calculated Net Cost: ${result.TotalPrice:F2}");
            }
            else
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine("  STATUS: Cart Rejected (FAILED)");
                foreach (var err in result.Errors)
                {
                    Console.WriteLine($"   * [Field: {err.PropertyName}] -> Description: {err.ErrorMessage}");
                }
            }
            Console.ResetColor();
            Console.WriteLine("--------------------------------------\n");
        }
    }
}
